          Image.ADAPTER.encodeWithTag(writer, 7, value.next_honor_icon)
        }
        if (value.level != 0) {
          ProtoAdapter.INT32.encodeWithTag(writer, 6, value.level)
        }
        if (value.next_honor_name != "") {
          ProtoAdapter.STRING.encodeWithTag(writer, 5, value.next_honor_name)
        }
        if (value.current_honor_icon != null) {
          Image.ADAPTER.encodeWithTag(writer, 4, value.current_honor_icon)
        }
        if (value.current_honor_name != "") {
          ProtoAdapter.STRING.encodeWithTag(writer, 3, value.current_honor_name)
        }
        if (value.diamond_icon != null) {
          Image.ADAPTER.encodeWithTag(writer, 2, value.diamond_icon)
        }
        if (value.total_diamond != 0L) {
          ProtoAdapter.INT64.encodeWithTag(writer, 1, value.total_diamond)
        }
      }

      override fun decode(reader: ProtoReader): UserHonor {
        var total_diamond: Long = 0L
        var diamond_icon: Image? = null
        var current_honor_name: String = ""
        var current_honor_icon: Image? = null
        var next_honor_name: String = ""
        var level: Int = 0
        var next_honor_icon: Image? = null
        var current_diamond: Long = 0L
        var this_grade_min_diamond: Long = 0L
        var this_grade_max_diamond: Long = 0L
        var grade_describe: String = ""
        val grade_icon_list = mutableListOf<GradeIcon>()
        var screen_chat_type: Long = 0L
        var im_icon: Image? = null
        var im_icon_with_level: Image? = null
        var live_icon: Image? = null
        var new_im_icon_with_level: Image? = null
        var new_live_icon: Image? = null
        var upgrade_need_consume: Long = 0L
        var next_privileges: String = ""
        var profile_dialog_bg: Image? = null
        var profile_dialog_back_bg: Image? = null
        var score: Long = 0L
        var grade_banner: String = ""
        val unknownFields = reader.forEachTag { tag ->
          when (tag) {
            1 -> total_diamond = ProtoAdapter.INT64.decode(reader)
            2 -> diamond_icon = Image.ADAPTER.decode(reader)
            3 -> current_honor_name = ProtoAdapter.STRING.decode(reader)
            4 -> current_honor_icon = Image.ADAPTER.decode(reader)
            5 -> next_honor_name = ProtoAdapter.STRING.decode(reader)
            6 -> level = ProtoAdapter.INT32.decode(reader)
            7 -> next_honor_icon = Image.ADAPTER.decode(reader)
            9 -> current_diamond = ProtoAdapter.INT64.decode(reader)
            10 -> this_grade_min_diamond = ProtoAdapter.INT64.decode(reader)
            11 -> this_grade_max_diamond = ProtoAdapter.INT64.decode(reader)
            13 -> grade_describe = ProtoAdapter.STRING.decode(reader)
            14 -> grade_icon_list.add(GradeIcon.ADAPTER.decode(reader))
            15 -> screen_chat_type = ProtoAdapter.INT64.decode(reader)
            16 -> im_icon = Image.ADAPTER.decode(reader)
            17 -> im_icon_with_level = Image.ADAPTER.decode(reader)
            18 -> live_icon = Image.ADAPTER.decode(reader)
            19 -> new_im_icon_with_level = Image.ADAPTER.decode(reader)
            20 -> new_live_icon = Image.ADAPTER.decode(reader)
            21 -> upgrade_need_consume = ProtoAdapter.INT64.decode(reader)
            22 -> next_privileges = ProtoAdapter.STRING.decode(reader)
            23 -> profile_dialog_bg = Image.ADAPTER.decode(reader)
            24 -> profile_dialog_back_bg = Image.ADAPTER.decode(reader)
            25 -> score = ProtoAdapter.INT64.decode(reader)
            1_001 -> grade_banner = ProtoAdapter.STRING.decode(reader)
            else -> reader.readUnknownField(tag)
          }
        }
        return UserHonor(
          total_diamond = total_diamond,
          diamond_icon = diamond_icon,
          current_honor_name = current_honor_name,
          current_honor_icon = current_honor_icon,
          next_honor_name = next_honor_name,
          level = level,
          next_honor_icon = next_honor_icon,
          current_diamond = current_diamond,
          this_grade_min_diamond = this_grade_min_diamond,
          this_grade_max_diamond = this_grade_max_diamond,
          grade_describe = grade_describe,
          grade_icon_list = grade_icon_list,
          screen_chat_type = screen_chat_type,
          im_icon = im_icon,
          im_icon_with_level = im_icon_with_level,
          live_icon = live_icon,
          new_im_icon_with_level = new_im_icon_with_level,
          new_live_icon = new_live_icon,
          upgrade_need_consume = upgrade_need_consume,
          next_privileges = next_privileges,
          profile_dialog_bg = profile_dialog_bg,
          profile_dialog_back_bg = profile_dialog_back_bg,
          score = score,
          grade_banner = grade_banner,
          unknownFields = unknownFields
        )
      }

      override fun redact(`value`: UserHonor): UserHonor = value.copy(
        diamond_icon = value.diamond_icon?.let(Image.ADAPTER::redact),
        current_honor_icon = value.current_honor_icon?.let(Image.ADAPTER::redact),
        next_honor_icon = value.next_honor_icon?.let(Image.ADAPTER::redact),
        grade_icon_list = value.grade_icon_list.redactElements(GradeIcon.ADAPTER),
        im_icon = value.im_icon?.let(Image.ADAPTER::redact),
        im_icon_with_level = value.im_icon_with_level?.let(Image.ADAPTER::redact),
        live_icon = value.live_icon?.let(Image.ADAPTER::redact),
        new_im_icon_with_level = value.new_im_icon_with_level?.let(Image.ADAPTER::redact),
        new_live_icon = value.new_live_icon?.let(Image.ADAPTER::redact),
        profile_dialog_bg = value.profile_dialog_bg?.let(Image.ADAPTER::redact),
        profile_dialog_back_bg = value.profile_dialog_back_bg?.let(Image.ADAPTER::redact),
        unknownFields = ByteString.EMPTY
      )
    }

